            tabs.forEach(tab => {
                tab.addEventListener('click', () => {
                    // Remove active from all tabs in this group
                    tabs.forEach(t => t.classList.remove('active'));
                    // Add active to clicked tab
                    tab.classList.add('active');

                    // Find corresponding content
                    const tabId = tab.dataset.tab;
                    const contentArea = tabGroup.closest('.section') || tabGroup.closest('.market-summary');
                    if (contentArea) {
                        const contents = contentArea.querySelectorAll('.tab-content');
                        contents.forEach(c => c.classList.remove('active'));
                        const targetContent = contentArea.querySelector(`[data-tab-content="${tabId}"]`);
                        if (targetContent) {
                            targetContent.classList.add('active');
                        }
                    }
                });
