    <script>
        // Generate candlestick data
        function generateCandlestickData(days = 90) {
            const data = [];
            let basePrice = 260;
            const now = new Date();

            for (let i = days; i >= 0; i--) {
                const date = new Date(now);
                date.setDate(date.getDate() - i);

                const volatility = 0.02;
                const trend = Math.sin(i / 20) * 0.005;
                const random = (Math.random() - 0.5) * volatility;

                const open = basePrice;
                const change = random + trend;
                const close = open * (1 + change);
                const high = Math.max(open, close) * (1 + Math.random() * 0.01);
                const low = Math.min(open, close) * (1 - Math.random() * 0.01);

                data.push({
                    x: date,
                    o: open,
                    h: high,
                    l: low,
                    c: close
                });

                basePrice = close;
            }
            return data;
        }

        // Initialize Chart
        const ctx = document.getElementById('candlestickChart').getContext('2d');
        const candlestickData = generateCandlestickData(90);

        // Simple candlestick chart using bar chart
        const chart = new Chart(ctx, {
            type: 'bar',
            data: {
                datasets: [{
                    label: 'AAPL',
                    data: candlestickData.map(d => ({
                        x: d.x,
                        o: d.o,
                        h: d.h,
                        l: d.l,
                        c: d.c
                    })),
                    backgroundColor: candlestickData.map(d => d.c >= d.o ? 'rgba(34, 197, 94, 0.8)' : 'rgba(247, 82, 95, 0.8)'),
                    borderColor: candlestickData.map(d => d.c >= d.o ? '#22C55E' : '#F7525F'),
                    borderWidth: 1,
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: {
                        display: false
                    },
                    tooltip: {
                        callbacks: {
                            label: function(context) {
                                const d = context.raw;
                                return [
                                    `Open: ${d.o.toFixed(2)}`,
                                    `High: ${d.h.toFixed(2)}`,
                                    `Low: ${d.l.toFixed(2)}`,
                                    `Close: ${d.c.toFixed(2)}`
                                ];
                            }
                        }
                    }
                },
                scales: {
                    x: {
                        type: 'time',
                        time: {
                            unit: 'day'
                        },
                        grid: {
                            color: 'rgba(255,255,255,0.05)'
                        },
                        ticks: {
                            color: '#6B6B7B',
                            maxRotation: 0
                        }
                    },
                    y: {
                        position: 'right',
                        grid: {
                            color: 'rgba(255,255,255,0.05)'
                        },
                        ticks: {
                            color: '#6B6B7B'
                        }
                    }
                }
            }
        });

        // Watchlist accordion
        document.querySelectorAll('.watchlist-section-header').forEach(header => {
            header.addEventListener('click', () => {
                const section = header.parentElement;
                section.classList.toggle('collapsed');
            });
        });

        // Timeframe buttons
        document.querySelectorAll('.timeframe-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                document.querySelectorAll('.timeframe-btn').forEach(b => b.classList.remove('active'));
                btn.classList.add('active');
            });
        });

        // Detail tabs
        document.querySelectorAll('.detail-tab').forEach(tab => {
            tab.addEventListener('click', () => {
                const tabGroup = tab.closest('.detail-tabs');
                tabGroup.querySelectorAll('.detail-tab').forEach(t => t.classList.remove('active'));
                tab.classList.add('active');

                const tabId = tab.dataset.detailTab;
                const contentArea = tab.closest('.detail-panel');
                contentArea.querySelectorAll('.detail-tab-content').forEach(c => c.classList.remove('active'));
                contentArea.querySelector(`[data-detail-content="${tabId}"]`).classList.add('active');
            });
        });

        // Financial tabs
        document.querySelectorAll('.financial-tab').forEach(tab => {
            tab.addEventListener('click', () => {
                const tabGroup = tab.parentElement;
                tabGroup.querySelectorAll('.financial-tab').forEach(t => t.classList.remove('active'));
                tab.classList.add('active');
            });
        });

        // Toolbar buttons
        document.querySelectorAll('.toolbar-btn').forEach(btn => {
            if (btn.querySelector('i')) {
                btn.addEventListener('click', () => {
                    if (!btn.classList.contains('timeframe-btn')) {
                        btn.classList.toggle('active');
                    }
                });
            }
        });
