            --accent-blue-hover: #1E50D0;
            --positive: #22C55E;
            --negative: #F7525F;
            --text-primary: #FFFFFF;
            --text-secondary: #A0A0B0;
            --text-muted: #6B6B7B;
            --border-color: #2A2A3E;
            --card-bg: #16162A;
        }

        * {
