            background: rgba(34, 197, 94, 0.15);
            color: var(--positive);
        }

        .idea-badge.bearish {
            background: rgba(247, 82, 95, 0.15);
            color: var(--negative);
        }

        .idea-card-body {
            padding: 16px;
        }

        .idea-ticker-row {
            display: flex;
            align-items: center;
            gap: 12px;
            margin-bottom: 12px;
        }

        .idea-ticker {
            font-size: 18px;
            font-weight: 700;
        }

        .idea-company {
            font-size: 13px;
            color: var(--text-secondary);
        }

        .idea-title {
            font-size: 14px;
            color: var(--text-secondary);
            line-height: 1.5;
            margin-bottom: 16px;
        }

        .idea-chart-preview {
            height: 80px;
            background: var(--bg-tertiary);
            border-radius: 6px;
            margin-bottom: 16px;
            display: flex;
            align-items: flex-end;
            padding: 8px;
            gap: 2px;
        }

        .chart-bar {
            flex: 1;
            background: var(--accent-blue);
            border-radius: 2px 2px 0 0;
            opacity: 0.7;
        }

        .chart-bar.up {
            background: var(--positive);
        }

        .chart-bar.down {
            background: var(--negative);
        }

        .idea-stats-row {
            display: flex;
            gap: 20px;
            padding-top: 12px;
            border-top: 1px solid var(--border-color);
        }

        .idea-stat {
            display: flex;
            flex-direction: column;
        }

        .idea-stat-label {
            font-size: 10px;
            color: var(--text-muted);
            text-transform: uppercase;
        }

        .idea-stat-value {
            font-size: 14px;
            font-weight: 600;
        }

        .idea-stat-value.positive {
            color: var(--positive);
        }

        .idea-stat-value.negative {
            color: var(--negative);
        }

        .idea-card-footer {
